INSERT INTO `chatbot_kb` (`title`, `content`, `category`, `active`, `created_at`, `updated_at`) VALUES
('Consultation medicale - Prendre rendez-vous', 'Pour consulter un medecin en ligne, rendez-vous sur la page de consultation et remplissez le formulaire. Lien: http://localhost/nufotec/patient-form?doctor_uuid=00009520-0bc2-f36c-4c37-00000000921c. Remplissez: nom, prenom, email, telephone, symptomes, date et heure souhaitees. Le medecin vous contactera ensuite.', 'Sante', 1, NOW(), NOW()),
('Symptomes courants - Quand consulter', 'Consultez un medecin si vous avez: fievre, maux de tetes persistants, douleurs abdominales, problems de peau, fatigue chronique, troubles du sommeil, ou tout symptome inquietant. Utilisez le formulaire de consultation pour prendre rendez-vous avec un de nos medecins qualifies.', 'Sante', 1, NOW(), NOW()),
('Comment remplir le formulaire de consultation', 'Etapes pour remplir le formulaire: 1) Selectionnez le medecin, 2) Entrez vos informations personnelles (nom, prenom), 3) Donnez votre email et telephone, 4) Decrivez vos symptomes en detail, 5) Choisissez la date et heure souhaitees, 6) Validez. Le formulaire se trouve sur la page patient-form.', 'Sante', 1, NOW(), NOW()),
('Medecins disponibles a Nufotec', 'Nufotec Burundi dispose de medecins qualifies en: medecine generale, dermatologie, pediatrie, cardiologie, et medecine interne. Chaque medecin a des horaires definis. Consultez le formulaire pour voir les medecins disponibles et leurs creneaux.', 'Sante', 1, NOW(), NOW()),
('Tarifs consultation medicale', 'Les tarifs de consultation varient selon le medecin et le type de consultation. Consultez le formulaire de consultation pour voir les honoraires de chaque medecin. Paiement possible via Mobile Money (Lumicash, EcoCash) ou en especes.', 'Sante', 1, NOW(), NOW());
